// ===========================================================================
//  CẤU HÌNH - rổ cổ phiếu "phơi nhiễm bất động sản"
// ===========================================================================
const BASKET = [
  { t: 'VHM', g: 'Chủ đầu tư' }, { t: 'VIC', g: 'Chủ đầu tư' }, { t: 'NVL', g: 'Chủ đầu tư' },
  { t: 'KDH', g: 'Chủ đầu tư' }, { t: 'DXG', g: 'Chủ đầu tư' }, { t: 'NLG', g: 'Chủ đầu tư' },
  { t: 'PDR', g: 'Chủ đầu tư' }, { t: 'DIG', g: 'Chủ đầu tư' },
  { t: 'BCM', g: 'BĐS Khu công nghiệp' }, { t: 'KBC', g: 'BĐS Khu công nghiệp' },
  { t: 'IDC', g: 'BĐS Khu công nghiệp' }, { t: 'SZC', g: 'BĐS Khu công nghiệp' },
  { t: 'VCB', g: 'Ngân hàng (cho vay BĐS)' }, { t: 'BID', g: 'Ngân hàng (cho vay BĐS)' },
  { t: 'CTG', g: 'Ngân hàng (cho vay BĐS)' }, { t: 'TCB', g: 'Ngân hàng (cho vay BĐS)' },
  { t: 'MBB', g: 'Ngân hàng (cho vay BĐS)' }, { t: 'STB', g: 'Ngân hàng (cho vay BĐS)' },
  { t: 'HPG', g: 'Xây dựng & vật liệu' }, { t: 'HSG', g: 'Xây dựng & vật liệu' }, { t: 'CTD', g: 'Xây dựng & vật liệu' },
];
const FOCUS = ['BID', 'BCM'];  // mã anh đang quan tâm - Claude đọc kỹ read-through tới đây
// ===========================================================================

const to   = Math.floor(Date.now() / 1000);
const from = to - 60 * 60 * 24 * 30;
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';
const hBar = { 'User-Agent': UA, 'Accept': '*/*' };
const hFlow = { 'User-Agent': UA, 'Accept': 'application/json', 'Referer': 'https://dstock.vndirect.com.vn/' };

const fetchBars = async (ticker) => {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET', url: 'https://services.entrade.com.vn/chart-api/v2/ohlcs/stock',
      qs: { symbol: ticker, from, to, resolution: '1D' }, headers: hBar, json: true, timeout: 15000,
    });
    if (res && Array.isArray(res.c) && res.c.length) return res;
  } catch (e) { /* dự phòng */ }
  const res = await this.helpers.httpRequest({
    method: 'GET', url: 'https://dchart-api.vndirect.com.vn/dchart/history',
    qs: { symbol: ticker, resolution: 'D', from, to },
    headers: { ...hBar, Referer: 'https://dchart.vndirect.com.vn/' }, json: true, timeout: 15000,
  });
  if (res && Array.isArray(res.c) && res.c.length) return res;
  return null;
};

const fetchNet5 = async (ticker) => {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api-finfo.vndirect.com.vn/v4/foreigns?q=code:' + ticker + '&size=5&sort=tradingDate:desc',
      headers: hFlow, json: true, timeout: 15000,
    });
    const data = (res && res.data) || [];
    return data.reduce((s, x) => s + (x.netVal || 0) / 1e9, 0);
  } catch (e) { return null; }
};

const groups = {};
const debug = [];

for (const { t, g } of BASKET) {
  try {
    const d = await fetchBars(t);
    if (!d || d.c.length < 6) { debug.push(t + ': thiếu dữ liệu giá'); continue; }
    const n = d.c.length;
    const pctDay = d.c[n - 2] ? (d.c[n - 1] / d.c[n - 2] - 1) * 100 : 0;
    const pct5   = d.c[n - 6] ? (d.c[n - 1] / d.c[n - 6] - 1) * 100 : 0;
    const net5   = await fetchNet5(t);
    groups[g] = groups[g] || { rows: [], sumDay: 0, sum5: 0, sumNet: 0, n: 0, netOk: 0 };
    const gr = groups[g];
    gr.rows.push({ t, pctDay, pct5, net5 });
    gr.sumDay += pctDay; gr.sum5 += pct5; gr.n++;
    if (net5 !== null) { gr.sumNet += net5; gr.netOk++; }
    debug.push(t + ': OK (ngày ' + pctDay.toFixed(1) + '%, 5p ' + pct5.toFixed(1) + '%, KN5p ' + (net5 === null ? 'n/a' : net5.toFixed(1)) + ')');
  } catch (e) {
    debug.push(t + ': ❌ ' + (e.message || String(e)));
  }
}

// Soạn phần dữ liệu cho Claude
let perf = '';
for (const g of Object.keys(groups)) {
  const gr = groups[g];
  perf += '[' + g + '] ' + gr.n + ' mã · TB hôm nay ' + (gr.sumDay / gr.n).toFixed(2) + '% · TB 5 phiên ' + (gr.sum5 / gr.n).toFixed(2) + '%'
        + ' · KN ròng 5 phiên ' + (gr.netOk ? gr.sumNet.toFixed(1) + ' tỷ' : 'n/a') + '\n';
  for (const r of gr.rows.sort((a, b) => b.pct5 - a.pct5)) {
    perf += '   ' + r.t + (FOCUS.includes(r.t) ? ' ⭐' : '') + ': hôm nay ' + r.pctDay.toFixed(1) + '%, 5 phiên ' + r.pct5.toFixed(1) + '%, KN ròng 5 phiên ' + (r.net5 === null ? 'n/a' : r.net5.toFixed(1) + ' tỷ') + '\n';
  }
  perf += '\n';
}

// Tin ngành (Google News)
const gn = (q) => 'https://news.google.com/rss/search?q=' + encodeURIComponent(q) + '&hl=vi&gl=VN&ceid=VN:vi';
const NEWS_FEEDS = [
  gn('bất động sản OR "thị trường nhà đất" when:5d'),
  gn('tín dụng bất động sản OR "trái phiếu doanh nghiệp" OR "khu công nghiệp" when:5d'),
  gn('lãi suất OR "Ngân hàng Nhà nước" OR "room tín dụng" when:5d'),
];
const pick = (xml, tag) => {
  const m = xml.match(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\\/' + tag + '>', 'i'));
  if (!m) return '';
  return m[1].replace(/<!\[CDATA\[/g, '').replace(/\]\]>/g, '').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/&#39;/g, "'").replace(/\s+/g, ' ').trim();
};
const news = [];
const seen = new Set();
for (const url of NEWS_FEEDS) {
  try {
    const body = await this.helpers.httpRequest({ method: 'GET', url, headers: { 'User-Agent': UA, 'Accept': '*/*' }, json: false, timeout: 20000 });
    const xml = typeof body === 'string' ? body : String(body);
    const blocks = (xml.match(/<item[\s\S]*?<\/item>/gi) || []).slice(0, 8);
    for (const it of blocks) {
      const title = pick(it, 'title');
      const key = title.toLowerCase().slice(0, 70);
      if (title && !seen.has(key)) { seen.add(key); news.push(title); }
    }
  } catch (e) { debug.push('Tin: ❌ ' + (e.message || String(e))); }
}
const newsText = news.length ? news.map((x, i) => (i + 1) + '. ' + x).join('\n') : '(không lấy được tin ngành)';

const today = new Date().toLocaleDateString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', day: 'numeric', month: 'numeric', year: 'numeric' });

const system = 'Bạn là chuyên viên phân tích NGÀNH Bất động sản & Tài chính Việt Nam, hỗ trợ một nhà đầu tư cá nhân. '
  + 'Nhiệm vụ: đọc dữ liệu hiệu suất + dòng tiền khối ngoại của rổ cổ phiếu phơi nhiễm bất động sản (chủ đầu tư, BĐS khu công nghiệp, ngân hàng cho vay BĐS, xây dựng-vật liệu) + tin ngành, viết BÁO CÁO NHỊP NGÀNH ngắn gọn bằng tiếng Việt.\n\n'
  + 'Nguyên tắc bắt buộc:\n'
  + '- Đánh giá sức khoẻ TỪNG NHÓM CON: đang được dòng tiền ủng hộ hay bị rút ra? (dựa vào TB % và KN ròng 5 phiên).\n'
  + '- READ-THROUGH cụ thể tới 2 mã đánh dấu ⭐ (BID, BCM): bối cảnh ngành đang thuận hay nghịch gió với 2 mã này?\n'
  + '- ĐỐI CHIẾU tin ngành với dòng tiền: tin tốt mà khối ngoại rút (hoặc ngược lại) là MÂU THUẪN cần nêu.\n'
  + '- Nêu yếu tố VĨ MÔ chi phối ngành (lãi suất, room tín dụng, trái phiếu doanh nghiệp) nếu tin có đề cập.\n'
  + '- Bố cục: (1) 🏗️ Tổng quan sức khoẻ ngành, (2) 🔍 Read-through BID & BCM, (3) ⚠️ Rủi ro & mâu thuẫn.\n'
  + '- TUYỆT ĐỐI KHÔNG khuyến nghị mua/bán cụ thể. KHÔNG bịa số liệu. Chưa rõ thì ghi "cần kiểm chứng".\n'
  + '- Ngắn gọn, dễ đọc trên điện thoại. Markdown đơn giản. Tối đa ~500 từ.';

const userContent = 'Tuần bắt đầu ' + today + '. Dữ liệu rổ ngành bất động sản (% giá: dương=tăng; KN ròng: dương=khối ngoại mua ròng, tỷ đồng):\n\n'
  + '=== HIỆU SUẤT & DÒNG TIỀN THEO NHÓM ===\n\n' + (perf || '(không lấy được dữ liệu rổ)')
  + '\n=== TIN NGÀNH ===\n\n' + newsText
  + '\n\nHãy viết báo cáo nhịp ngành theo đúng bố cục. Thiếu dữ liệu phần nào thì nói rõ.';

const requestBody = { model: 'claude-opus-4-8', max_tokens: 4000, system, messages: [{ role: 'user', content: userContent }] };

return [{ json: { requestBody, debug } }];

const res = $input.first().json;
let text = '';
if (res && Array.isArray(res.content)) text = res.content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
if (!text) {
  if (res && res.type === 'error' && res.error) text = '⚠️ Lỗi API: ' + (res.error.message || JSON.stringify(res.error));
  else if (res && res.stop_reason === 'refusal') text = '⚠️ Yêu cầu bị từ chối bởi bộ lọc an toàn.';
  else text = '⚠️ Không tạo được báo cáo (phản hồi rỗng).';
}
const now = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
const full = '🏘️ *NHỊP NGÀNH BẤT ĐỘNG SẢN*\n_' + now + '_\n\n' + text + '\n\n_Rổ BĐS/Ngân hàng/Xây dựng · DNSE/VNDirect + Google News · Tổng hợp bởi Claude AI · không phải khuyến nghị đầu tư_';
const SIZE = 3800;
const parts = [];
let s = full;
while (s.length > SIZE) { let cut = s.lastIndexOf('\n', SIZE); if (cut < SIZE * 0.5) cut = SIZE; parts.push(s.slice(0, cut)); s = s.slice(cut); }
if (s.trim()) parts.push(s);
return parts.map(p => ({ json: { message: p } }));
